<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
$admin=require_role(['owner','admin','operations']);
$pdo=Database::connection();$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf_or_fail();
 $packageId=filter_input(INPUT_POST,'package_id',FILTER_VALIDATE_INT)?:0;
 $date=(string)($_POST['slot_date']??'');$time=(string)($_POST['start_time']??'');
 $capacity=filter_input(INPUT_POST,'capacity',FILTER_VALIDATE_INT);
 if($packageId<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$time)||$capacity===false||$capacity===null||$capacity<1){$error='Check package, date, time, and capacity.';}
 else{try{$q=$pdo->prepare("INSERT INTO activity_slots (package_id,slot_date,start_time,capacity,status) SELECT id,:date,:time,:capacity,'open' FROM packages WHERE id=:package AND status='published'");$q->execute(['date'=>$date,'time'=>$time.':00','capacity'=>$capacity,'package'=>$packageId]);if($q->rowCount()!==1)throw new RuntimeException('Package not found or not published.');$message='Activity slot created.';}catch(Throwable $e){error_log('Slot create failed: '.$e->getMessage());$error='Could not create slot. The package/time may already exist.';}}
}
$packages=$pdo->query("SELECT id,name FROM packages WHERE status='published' ORDER BY name")->fetchAll();
$slots=$pdo->query("SELECT s.id,s.slot_date,s.start_time,s.capacity,s.reserved_count,s.status,p.name package_name FROM activity_slots s JOIN packages p ON p.id=s.package_id WHERE s.slot_date >= CURDATE() ORDER BY s.slot_date,s.start_time LIMIT 200")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activity slots | BTA Admin</title><style>:root{--orange:#ff5a1f}*{box-sizing:border-box}body{margin:0;background:#f4f2ed;color:#191919;font:14px/1.5 Arial,sans-serif}.top{background:#151515;color:#fff;padding:18px 24px;display:flex;justify-content:space-between}.top a{color:#fff}.wrap{max-width:1100px;margin:auto;padding:30px 20px}.panel{background:#fff;border:1px solid #e2ded6;border-top:3px solid var(--orange);padding:22px;margin:20px 0}.field{display:flex;flex-direction:column;gap:6px;margin:13px 0}.field label{font-size:11px;font-weight:800}.field input,.field select{padding:12px;border:1px solid #d7d2c9;font:inherit}.btn{padding:12px 16px;background:var(--orange);border:0;font-weight:900;cursor:pointer}.notice{padding:12px;background:#e5f4e7;margin:14px 0}.err{background:#fde8e5}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:12px;border-bottom:1px solid #e6e2da;white-space:nowrap}th{font-size:10px}@media(max-width:600px){.panel{padding:15px}.wrap{padding:22px 12px}}</style><link rel="stylesheet" href="../assets/css/admin-sidebar.css?v=20261024"></head><body><?php require __DIR__ . '/_sidebar.php'; ?><header class="top"><strong>BALI TARANTULA <span style="color:#ff5a1f">ADMIN</span></strong><a href="index.php">← Dashboard</a></header><main class="wrap"><h1>Activity slots</h1><p>Set capacity for each package date and start time. Reserved seats are tracked by the booking engine.</p><?php if($message):?><div class="notice"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="notice err"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Create slot</h2><?php if(!$packages):?><p>Create and publish a package first in the catalog.</p><?php else:?><form method="post"><?=csrf_field()?><div class="field"><label>PACKAGE</label><select name="package_id" required><?php foreach($packages as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="field"><label>ACTIVITY DATE</label><input type="date" name="slot_date" min="<?=e(date('Y-m-d'))?>" required></div><div class="field"><label>START TIME</label><input type="time" name="start_time" required></div><div class="field"><label>CAPACITY (PEOPLE)</label><input type="number" name="capacity" min="1" max="1000" value="20" required></div><button class="btn">CREATE SLOT</button></form><?php endif;?></section><section class="panel"><h2>Upcoming slots</h2><div class="tablewrap"><table><thead><tr><th>DATE</th><th>TIME</th><th>PACKAGE</th><th>CAPACITY</th><th>RESERVED</th><th>AVAILABLE</th><th>STATUS</th></tr></thead><tbody><?php foreach($slots as $s):?><tr><td><?=e($s['slot_date'])?></td><td><?=e(substr((string)$s['start_time'],0,5))?></td><td><?=e($s['package_name'])?></td><td><?=(int)$s['capacity']?></td><td><?=(int)$s['reserved_count']?></td><td><?=max(0,(int)$s['capacity']-(int)$s['reserved_count'])?></td><td><?=e($s['status'])?></td></tr><?php endforeach;?><?php if(!$slots):?><tr><td colspan="7">No upcoming slots.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>